    return all(
        not ((mask & (1 << u)) and (mask & (1 << v)))
        for u, v in indexed_edges
    )


def _selected_indices(mask, n):
    return tuple(i for i in range(n) if mask & (1 << i))


def _better_set(candidate, incumbent, n):
    if candidate.bit_count() != incumbent.bit_count():
        return candidate.bit_count() > incumbent.bit_count()
    return _selected_indices(candidate, n) < _selected_indices(incumbent, n)


def _repair_and_complete(mask, adjacency):
    """Repair conflicts, then greedily complete to a maximal independent set."""
    n = len(adjacency)
    selected = {i for i in range(n) if mask & (1 << i)}

    while selected:
        conflicting_degrees = {
            v: len(adjacency[v] & selected) for v in selected
        }
        victim = max(selected, key=lambda v: (conflicting_degrees[v], v))
        if conflicting_degrees[victim] == 0:
            break
        selected.remove(victim)

    available = {
        v for v in range(n)
        if v not in selected and not (adjacency[v] & selected)
    }
    while available:
        vertex = min(
            available,
            key=lambda v: (len(adjacency[v] & available), v),
        )
        selected.add(vertex)
        available.remove(vertex)
        available.difference_update(adjacency[vertex])

    return sum(1 << v for v in selected)


