            "two_qubit_gates_per_shot": int(two_qubit_gates),
            "total_two_qubit_gate_applications": int(two_qubit_gates * total_shots),
        },
        "independent_set_source": source,
        "raw_best_independent_set_size": raw_best_size,
        "matches_supplied_optimum": best_size == optimal_independent_set_size,
        "best_optimization_sample_energy": best_energy,
        "optimized_parameters": {
            "gamma": best_parameters[:p_layers].tolist(),
            "beta": best_parameters[p_layers:].tolist(),
        },
        "optimizer_success": bool(optimization_result.success),
        "optimizer_message": str(optimization_result.message),
    }


def main():
    vertices = [0, 1, 2, 3, 4]
    edges = [(0, 1), (1, 2), (2, 3), (3, 4)]
    coordinates_um = {0: 0.0, 1: 3.0, 2: 6.0, 3: 9.0, 4: 12.0}
    blockade_radius_um = 4.0

    geometric_edges = [
        (u, v)
        for i, u in enumerate(vertices)
        for v in vertices[i + 1:]
        if abs(coordinates_um[u] - coordinates_um[v]) <= blockade_radius_um
    ]
    assert geometric_edges == edges

    # At most one atom can be selected from each pair {0,1} and {2,3},
    # with at most one additional atom, 4. Thus alpha <= 3.
    # The set {0,2,4} achieves this bound and is the unique maximum.
    result = solve_mis_qaoa(
        graph_vertices=vertices,
        graph_edges=edges,
        optimal_independent_set_size=3,
    )
    assert result["independent_set"] == [0, 2, 4]
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
